code.formula:
@Command([EditDocument];"1");
@Command([FileSave]);

@If (Name= ""; @Return(@Do(@Command([EditGotoField];"Name") ;@Prompt([Ok];"Missing Value"; "Please enter Employee Name before proceeding!")));"");
@If (EmpNo= ""; @Return(@Do(@Command([EditGotoField];"EmpNo") ;@Prompt([Ok];"Missing Value"; "Please enter Employee No. before proceeding!")));"");
@If (Department= ""; @Return(@Do(@Command([EditGotoField];"Department") ;@Prompt([Ok];"Missing Value"; "Please enter Department before proceeding!")));"");
@If (SendTo= ""; @Return(@Do(@Command([EditGotoField];"SendTo") ;@Prompt([Ok];"Missing Value"; "Please select SendTo before proceeding!")));"");
@If (HOD= ""; @Return(@Do(@Command([EditGotoField];"HOD") ;@Prompt([Ok];"Missing Value"; "Please select the superior/ HOD before proceeding!")));"");
@If (Date= ""; @Return(@Do(@Command([EditGotoField];"Date") ;@Prompt([Ok];"Missing Value"; "Please enter Date Case before proceeding!")));"");
@If (Time= ""; @Return(@Do(@Command([EditGotoField];"Time") ;@Prompt([Ok];"Missing Value"; "Please enter Time/ Shift before proceeding!")));"");

FIELD SubmittedBy := @V3UserName;
FIELD SubmittedDate :=@Today;
FIELD CA :="Submitted";

@Command([FileSave]);

@MailSend(SendTo;CC:HOD:DocAuthor:HR;NULL;@DbTitle + " - Submitted for Reply : " + NotNum ;NULL;"Please follow this doclink   -----> " ;[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

@Command([EditDocument];"1");

@If (Reason= ""; @Return(@Do(@Command([EditGotoField];"Reason") ;@Prompt([Ok];"Missing Value"; "Please state your Reason before proceeding!")));"");
@If (repName= ""; @Return(@Do(@Command([EditGotoField];"repName") ;@Prompt([Ok];"Missing Value"; "Please enter Employee name before proceeding!")));"");
@If (repPosition= ""; @Return(@Do(@Command([EditGotoField];"repPosition") ;@Prompt([Ok];"Missing Value"; "Please state your Position before proceeding!")));"");

@If(hodStatus = "REJECTED"; FIELD hodStatus := "":FIELD hodDate := "":FIELD hodComment := "";"");

REM {FIELD repName :=@Name([CN];@UserName);};
FIELD repDate := @Today;
FIELD CA :="Submitted-HOD";

@Command([FileSave]);

@MailSend(HOD;SendTo;NULL;@DbTitle + " : For Your Approval -: " + NotNum;NULL;"Please follow this doclink ---> ";[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

@Command([EditDocument]; "1");

FIELD WDDate 			:=@Today;
FIELD WDBy 				:=@Name([CN];@UserName);
FIELD CA 					:="Withdrawn";
FIELD WDReason		:= @Prompt([OkCancelEdit]; "Enter Your Comment"; "Please state the reason for Withdrawal.";"");

@Command([FileSave]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

